import {createApi} from './client-api.js';
import {POSITIONS,COLORS,TEAM_NAMES,emptyState,id,quality,validateState,summarize,balancedDraw,swapPlayers,fromDraw,score,teamSummary,demoState} from './core.js';
const $=s=>document.querySelector(s);
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toLocaleUpperCase();
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date());
const dateText=date=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Sao_Paulo'}).format(new Date(date+'T12:00:00Z'));
const avg=value=>value===null?'—':value.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1});
let state=emptyState(),revision=0,ready=false,busy=false,conflicted=false,editingMatch=null;
let session=null,leagues=[],activeLeagueId=null,authBusy=false,loadGeneration=0,newLeagueId=null;
const ui={view:'inicio',search:'',position:'',archived:false,drawSearch:'',teamCount:2,selected:new Set(),metric:'goals',period:'all',minRated:0,matchFrom:'',matchTo:''};
$('#today').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date());
function notify(message){const dialog=document.querySelector('dialog[open]');if(dialog){let feedback=dialog.querySelector('.dialog-feedback');if(!feedback){feedback=document.createElement('p');feedback.className='dialog-feedback help';feedback.setAttribute('role','status');dialog.append(feedback);}feedback.textContent=message;}$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,6500);}
function setBusy(value){busy=value;document.querySelectorAll('[data-write]').forEach(button=>button.disabled=value||!ready||conflicted);document.querySelectorAll('[data-account-write]').forEach(button=>button.disabled=value||authBusy||!session?.profile);document.querySelectorAll('[data-auth-write]').forEach(button=>button.disabled=value||authBusy||(button.hasAttribute('data-needs-cloud')&&!session?.cloudReady));$('#active-league-select').disabled=value||authBusy;$('#sync-status').innerHTML=value?'<i></i>Salvando…':ready?(session?.profile?.kind==='guest'?'<i></i>Salvo neste navegador':'<i></i>Salvo na nuvem'):session?.profile?'<i></i>Minhas peladas':'<i></i>Acesso seguro';if($('#draw-button'))updateDrawCount();}
const api=createApi({storage:{getItem(key){try{return localStorage.getItem(key);}catch{throw Error('O armazenamento deste navegador está bloqueado.');}},setItem(key,value){localStorage.setItem(key,value);}}});
function rememberLeague(key){try{if(session?.profile)sessionStorage.setItem('varzuno-active:'+session.profile.id,key||'');}catch{}}
function rememberedLeague(){try{return session?.profile?sessionStorage.getItem('varzuno-active:'+session.profile.id):null;}catch{return null;}}
function updateChrome(){
 const profile=session?.profile;$('#account-button').textContent=profile?(profile.kind==='guest'?'Convidado':'Minha conta'):'Entrar';
 $('#sidebar-group').textContent=profile?.name||'Seu futebol, suas turmas';
 document.querySelector('.sidebar-bottom span').textContent=profile?(profile.kind==='guest'?'Sessão de convidado':'Conta por e-mail'):'Entre ou experimente como convidado';
 document.querySelectorAll('[data-nav]').forEach(a=>{a.hidden=a.dataset.nav!=='peladas'&&!activeLeagueId;const active=a.dataset.nav===ui.view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#league-switcher').hidden=!activeLeagueId||!profile||ui.authView;
 $('#active-league-select').innerHTML=leagues.map(l=>`<option value="${l.id}" ${l.id===activeLeagueId?'selected':''}>${h(l.name)}</option>`).join('');
 $('#settings-button').hidden=!activeLeagueId;
 let banners='';
 if(profile?.kind==='guest')banners='<div class="account-banner"><strong>Convidado local · sem proteção por senha.</strong><p>As peladas ficam apenas neste navegador. Para guardar na nuvem e usar em outros dispositivos, cadastre uma conta e transfira os registros. Exporte backups antes de limpar os dados do navegador.</p><button class="button secondary" data-action="go-login">Entrar / criar conta</button></div>';
 if(profile?.kind==='member'&&session.guestLeaguesAvailable)banners+=`<div class="account-banner"><strong>${session.guestLeaguesAvailable} pelada(s) locais encontradas neste navegador.</strong><p>Transfira-as para a conta para guardar os registros na nuvem.</p><button class="button primary" data-action="claim-guest" data-account-write>Transferir para minha conta</button></div>`;
 $('#account-banners').innerHTML=banners;setBusy(busy);
}
function authPage(){
 const cloud=session?.cloudReady,signup=ui.authMode==='register';
 const positions=Object.entries(POSITIONS).map(([key,label])=>`<option value="${key}" ${key==='MEI'?'selected':''}>${label}</option>`).join('');
 const form=signup?`<form id="register-form"><label for="register-name">Nome completo ou apelido</label><input id="register-name" required minlength="2" maxlength="50" autocomplete="name"><label for="register-email">E-mail</label><input id="register-email" type="email" required maxlength="254" autocomplete="email"><div class="form-grid"><div><label for="register-phone">Telefone com DDD</label><input id="register-phone" type="tel" required maxlength="24" autocomplete="tel" placeholder="(44) 99999-9999"></div><div><label for="register-position">Sua posição</label><select id="register-position">${positions}</select></div></div><label for="register-password">Senha · mínimo de 8 caracteres</label><input id="register-password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"><button class="button primary" data-auth-write data-needs-cloud>Criar minha conta</button><p id="register-error" class="form-error" role="alert"></p></form>`:`<form id="login-form"><label for="login-email">E-mail</label><input id="login-email" type="email" required maxlength="254" autocomplete="email"><label for="login-password">Senha</label><input id="login-password" type="password" required maxlength="128" autocomplete="current-password"><button class="button primary" data-auth-write data-needs-cloud>Entrar na minha conta</button><p id="login-error" class="form-error" role="alert"></p></form>`;
 return `<section class="auth-layout"><div class="auth-copy"><p class="eyebrow">SEU FUTEBOL. SUAS TURMAS.</p><h1>Um cadastro.<br>Todas as suas peladas.</h1><p>Reúna os atletas, sorteie times equilibrados e acompanhe cada partida. Cadastre nome, e-mail, telefone e posição para guardar suas peladas na conta.</p><div class="auth-features"><span>${icon('people')} Elencos separados</span><span>${icon('shuffle')} Sorteio equilibrado</span><span>${icon('trophy')} Rankings por pelada</span></div><div class="guest-entry"><h2>Prefere jogar sem cadastro?</h2><p>O convidado funciona agora e salva até 5 peladas neste navegador. Não há sincronização entre dispositivos.</p><form id="guest-form"><label for="guest-name">Seu nome ou apelido</label><input id="guest-name" value="Convidado" maxlength="50" minlength="2" required autocomplete="nickname"><button class="button lime" data-auth-write>Entrar como convidado ${icon('arrow')}</button><p id="guest-error" class="form-error" role="alert"></p></form></div></div><div class="panel auth-panel"><div class="auth-tabs"><button type="button" data-auth-mode="login" class="${signup?'':'active'}">Entrar</button><button type="button" data-auth-mode="register" class="${signup?'active':''}">Criar conta</button></div><h2>${signup?'Seu nome no vestiário.':'Bom ter você de volta.'}</h2>${!cloud?`<div class="setup-note" role="status"><strong>Cadastro na nuvem ainda não configurado.</strong><p>${h(session?.cloudMessage||'O responsável precisa conectar um banco Neon à Vercel e fazer Redeploy. Enquanto isso, use o convidado local.')}</p><a href="https://github.com/zrpires/varzuno/blob/main/docs/VERCEL.md" target="_blank" rel="noopener noreferrer">Ver configuração do banco</a></div>`:''}${form}<p class="help">Login pelo próprio aplicativo, usando seu e-mail e senha.</p>${session?.profile?.kind==='guest'?'<button type="button" class="link-button" data-action="cancel-auth">Voltar às minhas peladas locais</button>':''}</div></section>`;
}
function leaguesPage(){const profile=session.profile;return head('Cada turma, uma pelada.',`Olá, ${profile.name}. Seus elencos e resultados ficam separados por aqui.`,'MINHAS PELADAS',`<button class="button primary" data-action="create-league" data-account-write>${icon('plus')}Criar pelada</button>`)+`<div class="league-grid">${leagues.length?leagues.map(l=>`<article class="league-card"><div class="league-card-icon">${icon('ball')}</div><h2>${h(l.name)}</h2><div class="league-counts"><span><strong>${l.active_players}</strong> atletas ativos</span><span><strong>${l.match_count}</strong> partidas</span></div><p>Atualizada em ${dateText(l.updated_at.slice(0,10))}</p><div class="league-actions"><button class="button primary" data-action="open-league" data-id="${l.id}" data-account-write>Abrir pelada ${icon('arrow')}</button><button class="link-button" data-action="delete-league" data-id="${l.id}" data-account-write>Excluir</button></div></article>`).join(''):empty('Sua primeira turma começa aqui.','Crie uma pelada e cadastre seus atletas. Você pode organizar outras turmas sem misturar os registros.','<button class="button primary" data-action="create-league" data-account-write>Criar minha primeira pelada</button>','people')}</div><p class="help">${profile.kind==='guest'?'Modo convidado: até 5 peladas por sessão.':'Conta conectada: até 50 peladas.'} Cada pelada aceita até 300 atletas e 1.000 partidas.</p>`;}
async function refreshAccount(){
 const current=await api('/api/session');session=current;
 if(session.profile){leagues=(await api('/api/leagues')).leagues;}
 else leagues=[];
}
async function load(){
 if(busy||authBusy)return;const generation=++loadGeneration;$('#connection-error').hidden=true;
 try{
  await refreshAccount();if(generation!==loadGeneration)return;
  if(!session.profile){activeLeagueId=null;ready=false;state=emptyState();render();return;}
  const remembered=rememberedLeague(),target=leagues.find(l=>l.id===activeLeagueId)?.id||(ui.view!=='peladas'&&leagues.some(l=>l.id===remembered)?remembered:null);
  if(target){await openLeague(target,{fromLoad:true});return;}
  activeLeagueId=null;ready=false;ui.view='peladas';render();
 }catch(error){ready=false;$('#connection-error').hidden=false;$('#connection-error').innerHTML=`<strong>Não foi possível carregar sua conta.</strong><p>${h(error.message)}</p><button class="button secondary" data-action="reload">Tentar novamente</button>`;if($('#view').querySelector('.loading'))$('#view').innerHTML='<div class="empty"><h1>Seu vestiário está quase pronto.</h1><p>Confira a conexão e tente novamente. Seus registros não foram substituídos.</p></div>';setBusy(false);}
}
async function openLeague(key,{fromLoad=false}={}){
 if((busy||authBusy)&&!fromLoad)return;const generation=++loadGeneration;ready=false;conflicted=false;activeLeagueId=key;$('#connection-error').hidden=true;$('#view').innerHTML='<div class="loading">Carregando a pelada…</div>';setBusy(false);
 try{const result=await api('/api/leagues/'+encodeURIComponent(key));if(generation!==loadGeneration||activeLeagueId!==key)return;state=validateState(result.state);revision=result.revision;ready=true;rememberLeague(key);ui.search='';ui.position='';ui.drawSearch='';ui.selected=new Set(state.draw?state.draw.teams.flatMap(t=>t.playerIds):state.players.filter(p=>p.active).map(p=>p.id));ui.teamCount=state.draw?.teams.length||2;if(ui.view==='peladas')ui.view='inicio';location.hash=ui.view;render();}
 catch(error){if(generation!==loadGeneration)return;activeLeagueId=null;ready=false;ui.view='peladas';render();notify(error.message);}
}
async function commit(next,success){
  if(busy||!ready||conflicted||!activeLeagueId){notify(conflicted?'Recarregue os registros antes de continuar.':'Aguarde o carregamento ou o salvamento terminar.');return false;}
  let clean;try{clean=validateState(next);}catch(error){notify(error.message);return false;}
  setBusy(true);
  try{const result=await api('/api/leagues/'+encodeURIComponent(activeLeagueId),{method:'PUT',body:JSON.stringify({revision,state:clean})});state=validateState(result.state);revision=result.revision;const meta=leagues.find(l=>l.id===activeLeagueId);if(meta){meta.name=state.groupName;meta.revision=revision;meta.updated_at=new Date().toISOString();meta.active_players=state.players.filter(p=>p.active).length;meta.match_count=state.matches.length;}render();if(success)notify(success);return true;}
  catch(error){if(error.status===409){conflicted=true;$('#connection-error').hidden=false;$('#connection-error').innerHTML='<strong>Esta pelada foi atualizada em outra aba ou dispositivo.</strong><p>Seus dados não foram sobrescritos. Recarregue os registros e refaça a alteração desejada.</p><button class="button secondary" data-action="reload">Recarregar registros</button>';}notify(error.message);return false;}
  finally{setBusy(false);}
}
function head(title,subtitle,eyebrow,action=''){return `<div class="page-head"><div><p class="eyebrow">${h(eyebrow)}</p><h1>${h(title)}</h1><p>${h(subtitle)}</p></div>${action}</div>`;}
function playerOvr(p){return `<span class="overall ${quality(p.overall).toLowerCase()}" title="${quality(p.overall)} · overall ${p.overall}">${p.overall}</span>`;}
function athleteLine(p,extra=''){return `<div class="athlete-line"><span class="avatar" aria-hidden="true">${h(initials(p.name))}</span><div class="athlete-info"><strong>${h(p.name)}</strong><small>${POSITIONS[p.position]} · ${quality(p.overall)}</small></div>${extra||playerOvr(p)}</div>`;}
function empty(title,description,action='',symbol='ball'){return `<div class="empty">${icon(symbol)}<h3>${h(title)}</h3><p>${h(description)}</p>${action}</div>`;}
function activePlayers(){return state.players.filter(p=>p.active);}
function statCard(title,value,caption,symbol){return `<article class="stat-card"><div class="stat-top"><span>${h(title)}</span>${icon(symbol)}</div><strong>${h(value)}</strong><small>${h(caption)}</small></article>`;}
function dashboard(){
  const rows=summarize(state),matches=[...state.matches].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
  const goals=matches.reduce((n,m)=>n+score(m).reduce((a,b)=>a+b,0),0);
  const rated=rows.filter(r=>r.rated>0).sort((a,b)=>b.average-a.average||b.rated-a.rated);
  const top=[...rows].filter(p=>p.active).sort((a,b)=>b.overall-a.overall||a.name.localeCompare(b.name)).slice(0,5);
  return head('O jogo começa por aqui.','O vestiário da '+state.groupName+'.','VISÃO GERAL',`<button class="button primary" data-action="new-player" data-write>${icon('plus')}Novo atleta</button>`)+
  `<section class="hero-card" aria-label="Organizar a próxima pelada"><div class="hero-copy"><p class="eyebrow">A RESENHA VIROU ORGANIZAÇÃO.</p><h2>Times no equilíbrio.<br>Rivalidade só em campo.</h2><p>Reúna os confirmados, sorteie os times e deixe que os números contem o resto da história.</p><a class="button lime" href="#sorteio">Montar a próxima pelada ${icon('arrow')}</a></div><div class="hero-pitch" aria-hidden="true"><div class="pitch"><span class="penalty left"></span><span class="penalty right"></span><span class="shirt">1</span><span class="shirt">4</span><span class="shirt">8</span><span class="shirt">10</span><span class="shirt alt">7</span><span class="shirt alt">9</span><span class="shirt alt">1</span></div><span class="pitch-label">ONDE A TURMA VIRA TIME.</span></div></section>`+
  `<div class="stats-grid">${statCard('Atletas no elenco',activePlayers().length,'ativos e prontos para jogar','people')}${statCard('Partidas registradas',matches.length,'histórico da sua pelada','calendar')}${statCard('Gols na conta',goals,'inclui gols sem autoria','ball')}${statCard('Melhor média',rated.length?avg(rated[0].average):'—',rated.length?rated[0].name:'as notas aparecem após os jogos','trophy')}</div>`+
  `<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Últimas partidas</h2><a href="#partidas">Ver histórico</a></div>${matches.length?matches.slice(0,3).map(m=>matchCard(m,true)).join(''):empty('A primeira história ainda vai ser escrita.','Cadastre a turma e faça o sorteio. Depois da partida, registre os gols e as atuações.','<a href="#sorteio" class="button secondary">Preparar os times</a>','ball')}</section><section class="panel"><div class="panel-head"><h2>Os nomes do elenco</h2><span class="chip">POR OVERALL</span></div>${top.length?top.map(p=>athleteLine(p)).join(''):empty('Todo craque começa no cadastro.','Adicione nome, posição e overall para organizar os primeiros times.',`<button class="button secondary" data-action="new-player" data-write>Adicionar primeiro atleta</button>${!state.players.length?'<button class="link-button" data-action="demo" data-write>Ou explorar com dados de exemplo</button>':''}`,'people')}${top.length?'<a href="#atletas" class="link-button">Conhecer todo o elenco</a>':''}</section></div>`;
}
function athleteCards(){
  const rows=summarize(state),matches=rows.filter(p=>(ui.archived||p.active)&&(!ui.position||p.position===ui.position)&&p.name.toLocaleLowerCase().includes(ui.search.toLocaleLowerCase())).sort((a,b)=>b.overall-a.overall||a.name.localeCompare(b.name));
  if(!matches.length)return empty(state.players.length?'Nenhum atleta nesse filtro.':'Quem vai para o jogo?','Cadastre sua turma e atribua um overall de 1 a 99.',`<button class="button primary" data-action="new-player" data-write>Adicionar atleta</button>`,'people');
  return matches.map(p=>`<article class="athlete-card ${p.active?'':'archived'}"><div class="athlete-top"><span class="avatar" aria-hidden="true">${h(initials(p.name))}</span><div><h3>${h(p.name)}</h3><p>${POSITIONS[p.position]} · ${quality(p.overall)}</p>${p.active?'':'<span class="archive-label">Arquivado</span>'}</div>${playerOvr(p)}</div><div class="athlete-numbers"><div><strong>${p.appearances}</strong><span>PARTICIPAÇÕES</span></div><div><strong>${p.goals}</strong><span>GOLS</span></div><div><strong>${avg(p.average)}</strong><span>MÉDIA DE NOTAS</span></div></div><div class="athlete-actions"><button class="button secondary" data-action="edit-player" data-id="${p.id}" data-write>Editar atleta</button><button class="link-button" data-action="archive-player" data-id="${p.id}" data-write>${p.active?'Arquivar':'Reativar'}</button></div></article>`).join('');
}
function athletes(){return head('A turma que faz o jogo.','Overall para equilibrar. Posição para organizar. Ninguém fica sem identidade.','ELENCO',`<button class="button primary" data-action="new-player" data-write>${icon('plus')}Novo atleta</button>`)+`<div class="toolbar"><label class="sr-only" for="athlete-search">Buscar atleta</label><input id="athlete-search" type="search" placeholder="Buscar por nome ou apelido" value="${h(ui.search)}"><label class="sr-only" for="athlete-position">Filtrar por posição</label><select id="athlete-position"><option value="">Todas as posições</option>${Object.entries(POSITIONS).map(([k,v])=>`<option value="${k}" ${ui.position===k?'selected':''}>${v}</option>`).join('')}</select><label class="muted push"><input id="show-archived" type="checkbox" ${ui.archived?'checked':''}> Incluir arquivados</label></div><div class="athletes-grid" id="athlete-list">${athleteCards()}</div><p class="storage-explainer">Arquivar remove o atleta dos próximos sorteios e preserva seu histórico. Para diferenciá-los, use apelidos únicos.</p>`;}
function drawList(){const players=activePlayers().filter(p=>p.name.toLocaleLowerCase().includes(ui.drawSearch.toLocaleLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));return players.length?players.map(p=>`<label class="selection-row"><input type="checkbox" data-select-player="${p.id}" ${ui.selected.has(p.id)?'checked':''}><span class="selection-label">${h(p.name)}<small>${POSITIONS[p.position]}</small></span>${playerOvr(p)}</label>`).join(''):empty('Ninguém encontrado.','Cadastre atletas ou ajuste sua busca.','','people');}
function teamCards(){return state.draw.teams.map(team=>{const summary=teamSummary(team,state.players);return `<section class="team-card"><div class="team-head"><h3><span class="team-dot" style="--team-color:${team.color}" aria-hidden="true"></span>${h(team.name)}</h3><span class="team-average">OVERALL <strong>${avg(summary.average)}</strong></span></div><div class="team-roster">${team.playerIds.map(pid=>state.players.find(p=>p.id===pid)).filter(Boolean).map(p=>`<div class="athlete-line"><span class="position-code">${p.position}</span><div class="athlete-info"><strong>${h(p.name)}</strong><small>${POSITIONS[p.position]}</small></div>${playerOvr(p)}</div>`).join('')}<p class="help">${summary.count} atletas · ${summary.keepers} goleiro(s)</p></div></section>`;}).join('');}
function drawResult(){
  if(!state.draw)return empty('Sem panela. Com equilíbrio.','Selecione os confirmados ao lado. O sorteio considera overall, quantidade de jogadores e grupos de posição.','','shuffle');
  const summaries=state.draw.teams.map(t=>teamSummary(t,state.players)),difference=Math.max(...summaries.map(t=>t.average))-Math.min(...summaries.map(t=>t.average));
  const keepers=summaries.reduce((n,t)=>n+t.keepers,0),count=state.draw.teams.length;
  const warnings=[];if(keepers<count)warnings.push(`Há ${keepers} goleiro(s) para ${count} times. A turma precisará revezar no gol.`);if(new Set(summaries.map(t=>t.count)).size>1)warnings.push('As quantidades diferem em um atleta. Combine o revezamento com a turma.');if(state.draw.teams.some(t=>t.playerIds.some(pid=>!state.players.find(p=>p.id===pid)?.active)))warnings.push('Há atleta arquivado neste sorteio. Gere novos times antes de registrar uma partida.');
  const options=state.draw.teams.flatMap(t=>t.playerIds.map(pid=>({team:t,player:state.players.find(p=>p.id===pid)}))).filter(x=>x.player).map(x=>`<option value="${x.player.id}">${h(x.player.name)} · ${h(x.team.name)}</option>`).join('');
  return `<div class="panel-head"><div><p class="eyebrow">A TURMA ESTÁ DIVIDIDA.</p><h2>Agora é resolver em campo.</h2></div><button class="button secondary draw-share" data-action="share-teams">Copiar times</button></div><div class="team-grid">${teamCards()}</div><div class="balance-note">Diferença entre médias: <strong>${avg(difference)} ponto(s) de overall.</strong> O sorteio busca equilíbrio por médias e posições; não garante a combinação matematicamente ótima.</div>${warnings.map(w=>`<div class="balance-note warning">${h(w)}</div>`).join('')}<details class="swap-panel"><summary>Ajustar uma troca entre os times</summary><div class="swap-fields"><div><label for="swap-a">Primeiro atleta</label><select id="swap-a">${options}</select></div><div><label for="swap-b">Segundo atleta</label><select id="swap-b">${options}</select></div><button class="button secondary" data-action="swap" data-write>Trocar</button></div><p class="help">Trocas manuais podem mudar o equilíbrio. As médias são atualizadas imediatamente após salvar.</p></details><div class="start-match"><div><label for="match-team-a">Primeiro time</label><select id="match-team-a">${state.draw.teams.map((t,i)=>`<option value="${t.id}">${h(t.name)}</option>`).join('')}</select></div><div><label for="match-team-b">Segundo time</label><select id="match-team-b">${state.draw.teams.map((t,i)=>`<option value="${t.id}" ${i===1?'selected':''}>${h(t.name)}</option>`).join('')}</select></div><button class="button primary" data-action="new-match" data-write>${icon('ball')}Registrar partida</button></div><p class="help">Com três ou quatro times, registre cada confronto separadamente. Quem ficou de fora não recebe participação.</p>`;
}
function drawView(){return head('O fim da famosa panela.','Sorteie de 2 a 4 times, com todos os confirmados distribuídos.','SORTEIO')+`<div class="draw-layout"><section class="panel"><div class="panel-head"><h2>Quem confirmou?</h2><span class="chip" id="draw-count">0 selecionados</span></div><label for="team-count">Quantidade de times</label><select id="team-count">${[2,3,4].map(n=>`<option value="${n}" ${ui.teamCount===n?'selected':''}>${n} times</option>`).join('')}</select><label for="draw-search">Buscar atleta</label><input id="draw-search" type="search" value="${h(ui.drawSearch)}" placeholder="Nome ou apelido"><div class="list-controls"><button class="link-button" data-action="select-all">Marcar todos</button><button class="link-button" data-action="select-none">Limpar seleção</button></div><div class="draw-list" id="draw-list">${drawList()}</div><div class="draw-actions"><button class="button primary" id="draw-button" data-action="draw" data-write>${icon('shuffle')}Sortear times</button></div><p class="help">Mínimo de 2 atletas por time. Até 60 confirmados. Goleiros são distribuídos primeiro.</p></section><section id="draw-result">${drawResult()}</section></div>`;}
function updateDrawCount(){const available=new Set(activePlayers().map(p=>p.id));ui.selected=new Set([...ui.selected].filter(id=>available.has(id)));if($('#draw-count'))$('#draw-count').textContent=ui.selected.size+' selecionados';if($('#draw-button'))$('#draw-button').disabled=busy||!ready||conflicted||ui.selected.size<ui.teamCount*2||ui.selected.size>60;}
function matchCard(m,compact=false){const totals=score(m),participants=m.teams.flatMap(t=>t.players).filter(p=>p.played).length;return `<article class="match-card"><div class="match-meta"><span>${icon('calendar')} ${dateText(m.date)}</span><span>${m.location?h(m.location):'Local não informado'}</span></div><div class="scoreline"><span class="team-name"><span class="team-dot" style="--team-color:${m.teams[0].color}" aria-hidden="true"></span> ${h(m.teams[0].name)}</span><strong class="score-number">${totals[0]}<span>×</span>${totals[1]}</strong><span class="team-name">${h(m.teams[1].name)} <span class="team-dot" style="--team-color:${m.teams[1].color}" aria-hidden="true"></span></span></div><div class="match-foot"><span>${participants} participações · ${m.teams.flatMap(t=>t.players).filter(p=>p.played&&p.rating!==null).length} notas</span><div class="spaced"><button class="button secondary" data-action="edit-match" data-id="${m.id}" data-write>Ver / editar</button>${compact?'':`<button class="link-button" data-action="delete-match" data-id="${m.id}" data-write>Excluir</button>`}</div></div>${compact?'':`<details class="match-details"><summary>Ver atuações e anotações</summary><div class="table-wrap"><table><thead><tr><th>Atleta</th><th>Time</th><th>Gols</th><th>Assist.</th><th>Nota</th></tr></thead><tbody>${m.teams.flatMap(t=>t.players.filter(p=>p.played).map(p=>`<tr><td>${h(p.name)}</td><td>${h(t.name)}</td><td>${p.goals}</td><td>${p.assists}</td><td>${avg(p.rating)}</td></tr>`)).join('')}</tbody></table></div>${m.extraGoals.some(n=>n)?`<p class="help">Gols sem autoria / contra a favor: ${h(m.teams[0].name)} ${m.extraGoals[0]} · ${h(m.teams[1].name)} ${m.extraGoals[1]}.</p>`:''}${m.notes?`<p class="help">${h(m.notes)}</p>`:''}</details>`}</article>`;}
function matchesList(){const matches=[...state.matches].filter(m=>(!ui.matchFrom||m.date>=ui.matchFrom)&&(!ui.matchTo||m.date<=ui.matchTo)).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));return matches.length?matches.map(m=>matchCard(m)).join(''):empty(state.matches.length?'Nenhuma partida neste período.':'O apito final é só o começo.','Depois de sortear os times, registre o confronto, os gols, as assistências e as notas.','<a class="button primary" href="#sorteio">Preparar confronto</a>','ball');}
function matchesView(){return head('Cada jogo deixa uma história.','O placar, os números e a resenha da sua turma ficam por aqui.','PARTIDAS','<a href="#sorteio" class="button primary">'+icon('plus')+'Registrar partida</a>')+`<div class="toolbar history-filters"><div><label for="match-from">De</label><input id="match-from" type="date" value="${h(ui.matchFrom)}"></div><div><label for="match-to">Até</label><input id="match-to" type="date" value="${h(ui.matchTo)}"></div><button class="link-button" data-action="clear-dates">Limpar período</button></div><div id="matches-list">${matchesList()}</div>`;}
function periodFrom(){if(ui.period==='month')return today().slice(0,7)+'-01';if(ui.period==='30'){const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-29);return d.toISOString().slice(0,10);}return '';}
function rankingRows(){return summarize(state,{from:periodFrom(),minRated:ui.metric==='average'?ui.minRated:0}).sort((a,b)=>(ui.metric==='average'?(b.average??-1)-(a.average??-1):b[ui.metric]-a[ui.metric])||b.appearances-a.appearances||a.name.localeCompare(b.name));}
function rankingTable(){const rows=rankingRows();if(!rows.length)return empty('Ainda não há números para esse filtro.','Registre partidas e notas ou diminua o mínimo de avaliações.','','trophy');return `<div class="table-wrap"><table><thead><tr><th>Atleta</th><th>OVR</th><th>Gols</th><th>Assist.</th><th>G+A</th><th>Particip.</th><th>Média</th><th>V / E / D</th><th>Pontos</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><div class="rank-name"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="avatar" aria-hidden="true">${h(initials(r.name))}</span><div><strong>${h(r.name)}</strong><small>${POSITIONS[r.position]}${r.active?'':' · arquivado'}</small></div></div></td><td>${playerOvr(r)}</td><td>${r.goals}</td><td>${r.assists}</td><td>${r.contributions}</td><td>${r.appearances}</td><td><span class="rating">${avg(r.average)}</span><small class="muted"> (${r.rated})</small></td><td>${r.wins} / ${r.draws} / ${r.losses}</td><td>${r.points}</td></tr>`).join('')}</tbody></table></div>`;}
function rankingView(){const rows=summarize(state,{from:periodFrom()});const featured=[{label:'NA ARTILHARIA',metric:'goals',unit:'gol(s)'},{label:'O GARÇOM DA TURMA',metric:'assists',unit:'assistência(s)'},{label:'PRESENÇA CONFIRMADA',metric:'appearances',unit:'partida(s)'}].map(type=>{const p=[...rows].filter(p=>p[type.metric]>0).sort((a,b)=>b[type.metric]-a[type.metric]||a.name.localeCompare(b.name))[0];return `<article class="podium-card"><p class="eyebrow">${type.label}</p><h3>${p?h(p.name):'A definir em campo'}</h3><strong>${p?p[type.metric]:'—'}</strong><small>${p?type.unit:'registre uma partida para começar'}</small></article>`;}).join('');return head('Os números não entram na resenha.','Descubra quem decide, quem serve e quem nunca falta.','RANKING',`<button class="button secondary" data-action="export-ranking">Exportar CSV</button>`)+`<div class="podium-grid">${featured}</div><div class="toolbar"><div><label for="rank-metric">Classificar por</label><select id="rank-metric">${Object.entries({goals:'Gols',assists:'Assistências',overall:'Overall',average:'Média de notas',appearances:'Participações',points:'Pontos',contributions:'Participações em gols (G+A)'}).map(([key,label])=>`<option value="${key}" ${ui.metric===key?'selected':''}>${label}</option>`).join('')}</select></div><div><label for="rank-period">Período</label><select id="rank-period"><option value="all">Todo o histórico</option><option value="month" ${ui.period==='month'?'selected':''}>Mês atual</option><option value="30" ${ui.period==='30'?'selected':''}>Últimos 30 dias</option></select></div><div ${ui.metric==='average'?'':'hidden'}><label for="rank-min">Mínimo de notas</label><select id="rank-min">${[0,3,5,10].map(n=>`<option value="${n}" ${ui.minRated===n?'selected':''}>${n===0?'Sem mínimo':n+' avaliações'}</option>`).join('')}</select></div></div><div id="ranking-table">${rankingTable()}</div><p class="ranking-rule">Particip. = partidas disputadas · G+A = gols + assistências · Média considera apenas notas preenchidas (quantidade entre parênteses) · Pontos: 3 por vitória, 1 por empate. Atletas arquivados preservam suas estatísticas.</p>`;}
function render(){
 if(!session)return;
 if(!session.profile||ui.authView){$('#view').innerHTML=authPage();$('#nav-count').textContent='0';updateChrome();return;}
 if(ui.view==='peladas'||!activeLeagueId){ui.view='peladas';$('#view').innerHTML=leaguesPage();$('#nav-count').textContent='0';updateChrome();return;}
 if(!ready)return;
 $('#nav-count').textContent=activePlayers().length;const pages={inicio:dashboard,atletas:athletes,sorteio:drawView,partidas:matchesView,ranking:rankingView};$('#view').innerHTML=(pages[ui.view]||dashboard)();updateChrome();
}
function route(){ui.authView=false;const key=location.hash.slice(1);ui.view=['peladas','inicio','atletas','sorteio','partidas','ranking'].includes(key)?key:'peladas';if(session?.profile&&!activeLeagueId&&ui.view!=='peladas')ui.view='peladas';render();}
window.addEventListener('hashchange',route);
function openPlayer(pid){document.querySelectorAll('.dialog-feedback').forEach(n=>n.remove());if(!ready||busy||conflicted)return;const p=state.players.find(p=>p.id===pid);$('#player-title').textContent=p?'Editar atleta':'Novo atleta';$('#player-id').value=p?.id||'';$('#player-name').value=p?.name||'';$('#player-position').value=p?.position||'MEI';$('#player-overall').value=p?.overall||75;$('#player-error').textContent='';$('#player-dialog').showModal();}
$('#player-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const existing=state.players.find(p=>p.id===$('#player-id').value);const player={id:existing?.id||id(),name:$('#player-name').value.trim(),position:$('#player-position').value,overall:Number($('#player-overall').value),active:existing?.active??true,createdAt:existing?.createdAt||new Date().toISOString()};const next=structuredClone(state);if(existing)next.players=next.players.map(p=>p.id===player.id?player:p);else next.players.push(player);$('#player-error').textContent='';if(await commit(next,existing?'Atleta atualizado.':'Atleta escalado para a turma.')){if(player.active)ui.selected.add(player.id);$('#player-dialog').close();if(ui.view==='sorteio'){render();}}else $('#player-error').textContent='Confira os dados e a mensagem de erro antes de tentar novamente.';});
function matchFields(m){const totals=score(m);return `<div class="match-date-fields"><div><label for="match-date">Data da partida</label><input id="match-date" type="date" value="${m.date}" max="${today()}" required></div><div><label for="match-location">Local (opcional)</label><input id="match-location" maxlength="100" value="${h(m.location)}" placeholder="Ex.: Quadra do bairro"></div></div><div class="live-score"><span>${h(m.teams[0].name)}</span><strong><span id="live-score-a">${totals[0]}</span> × <span id="live-score-b">${totals[1]}</span></strong><span>${h(m.teams[1].name)}</span></div><p class="help">Marque apenas quem jogou. Gols e assistências são números inteiros. Nota opcional de 0 a 10; em branco significa sem avaliação. O placar é calculado pelos gols registrados.</p>${m.teams.map((t,ti)=>`<section class="performance-team"><h3><span class="team-dot" style="--team-color:${t.color}" aria-hidden="true"></span>${h(t.name)}</h3><div class="table-wrap"><table><thead><tr><th>Atleta</th><th>Jogou?</th><th>Gols</th><th>Assist.</th><th>Nota</th></tr></thead><tbody>${t.players.map((p,pi)=>`<tr data-perf-team="${ti}" data-perf-player="${pi}"><td>${h(p.name)}<small>${POSITIONS[p.position]} · OVR ${p.overall}</small></td><td><input type="checkbox" data-field="played" aria-label="${h(p.name)} jogou" ${p.played?'checked':''}></td><td><input data-field="goals" aria-label="Gols de ${h(p.name)}" type="number" min="0" max="30" step="1" value="${p.goals}" ${p.played?'':'disabled'}></td><td><input data-field="assists" aria-label="Assistências de ${h(p.name)}" type="number" min="0" max="30" step="1" value="${p.assists}" ${p.played?'':'disabled'}></td><td><input data-field="rating" aria-label="Nota de ${h(p.name)}" type="number" min="0" max="10" step="0.1" placeholder="—" value="${p.rating??''}" ${p.played?'':'disabled'}></td></tr>`).join('')}</tbody></table></div><div class="extra-goals"><label for="extra-${ti}">Gols sem autoria / contra a favor de ${h(t.name)}</label><input id="extra-${ti}" type="number" min="0" max="30" step="1" value="${m.extraGoals[ti]}"></div></section>`).join('')}<p class="help">Gols sem autoria somam no placar, mas não na artilharia. Assistências só podem ser atribuídas aos gols com autor identificado no próprio time.</p><label for="match-notes">Anotações da partida (opcional)</label><textarea id="match-notes" maxlength="500" rows="2" placeholder="Aquela defesa que mereceu entrar para a história…">${h(m.notes)}</textarea>`;}
function openMatch(match){document.querySelectorAll('.dialog-feedback').forEach(n=>n.remove());editingMatch=structuredClone(match);$('#match-title').textContent=state.matches.some(m=>m.id===match.id)?'Editar resultado':'Registrar partida';$('#match-fields').innerHTML=matchFields(editingMatch);$('#match-error').textContent='';$('#match-dialog').showModal();setBusy(busy);}
function readMatch(){const m=structuredClone(editingMatch);m.date=$('#match-date').value;m.location=$('#match-location').value.trim();m.notes=$('#match-notes').value.trim();m.updatedAt=new Date().toISOString();m.extraGoals=[Number($('#extra-0').value||0),Number($('#extra-1').value||0)];document.querySelectorAll('[data-perf-team]').forEach(row=>{const p=m.teams[Number(row.dataset.perfTeam)].players[Number(row.dataset.perfPlayer)];p.played=row.querySelector('[data-field="played"]').checked;p.goals=p.played?Number(row.querySelector('[data-field="goals"]').value||0):0;p.assists=p.played?Number(row.querySelector('[data-field="assists"]').value||0):0;const v=row.querySelector('[data-field="rating"]').value;p.rating=p.played&&v!==''?Number(v):null;});return m;}
function updateLiveScore(){if(!editingMatch)return;const totals=score(readMatch());$('#live-score-a').textContent=totals[0];$('#live-score-b').textContent=totals[1];}
$('#match-form').addEventListener('input',event=>{if(event.target.dataset.field==='played'){const row=event.target.closest('tr');for(const field of ['goals','assists','rating']){const input=row.querySelector(`[data-field="${field}"]`);input.disabled=!event.target.checked;if(!event.target.checked)input.value=field==='rating'?'':0;}}updateLiveScore();});
$('#match-form').addEventListener('submit',async event=>{event.preventDefault();if(busy||!editingMatch)return;try{const match=readMatch(),next=structuredClone(state);const index=next.matches.findIndex(m=>m.id===match.id);if(index<0)next.matches.push(match);else next.matches[index]=match;validateState(next);$('#match-error').textContent='';if(await commit(next,index<0?'Partida registrada. Os números já estão no ranking.':'Resultado corrigido, sem duplicar as estatísticas.')){$('#match-dialog').close();editingMatch=null;}}catch(error){$('#match-error').textContent=error.message;}});
function closeMatch(){if(busy)return;if(confirm('Fechar a ficha? Alterações não salvas serão descartadas.')){$('#match-dialog').close();editingMatch=null;}}
$('#close-match').onclick=closeMatch;$('#cancel-match').onclick=closeMatch;$('#match-dialog').addEventListener('cancel',e=>{e.preventDefault();closeMatch();});
function download(name,value,type){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBackup(){if(!ready)return notify('Carregue os registros antes de exportar.');download('varzuno-backup-'+today()+'.json',JSON.stringify({format:'varzuno-backup',version:1,exportedAt:new Date().toISOString(),state},null,2),'application/json');}
function csvCell(value){let text=String(value??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}
function exportRanking(){if(!ready)return;const rows=[['Atleta','Posição','Overall','Gols','Assistências','G+A','Participações','Média','Notas','Vitórias','Empates','Derrotas','Pontos'],...rankingRows().map(r=>[r.name,POSITIONS[r.position],r.overall,r.goals,r.assists,r.contributions,r.appearances,r.average===null?'':r.average.toFixed(2),r.rated,r.wins,r.draws,r.losses,r.points])];download('varzuno-ranking-'+today()+'.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
async function shareTeams(){if(!state.draw)return;const text=state.groupName+' · Várzuno\n\n'+state.draw.teams.map(t=>t.name+' (OVR '+avg(teamSummary(t,state.players).average)+')\n'+t.playerIds.map(pid=>state.players.find(p=>p.id===pid)).filter(Boolean).map(p=>'• '+p.name+' · '+p.position+' · '+p.overall).join('\n')).join('\n\n');try{await navigator.clipboard.writeText(text);notify('Times copiados. Agora é mandar para a turma.');}catch{$('#share-text').value=text;$('#text-dialog').showModal();$('#share-text').select();}}
$('#settings-button').onclick=()=>{if(!ready)return notify('Conecte-se e carregue seus registros primeiro.');$('#group-name').value=state.groupName;$('#settings-dialog').showModal();setBusy(busy);};
$('#group-form').onsubmit=async event=>{event.preventDefault();await commit({...state,groupName:$('#group-name').value.trim()},'A pelada agora tem nome.');};
$('#export-backup').onclick=exportBackup;
$('#import-backup').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>2000000)throw Error('O backup deve ter até 2 MB.');const data=JSON.parse(await file.text());if(data.format!=='varzuno-backup'||data.version!==1)throw Error('Escolha um backup exportado pelo Várzuno.');const clean=validateState(data.state);if(!confirm(`Restaurar ${clean.players.length} atletas e ${clean.matches.length} partidas? Os dados atuais serão substituídos. Exporte um backup antes, se necessário.`))return;if(await commit(clean,'Backup restaurado.')){ui.selected=new Set(clean.players.filter(p=>p.active).map(p=>p.id));$('#settings-dialog').close();render();}}catch(error){notify('Não foi possível restaurar: '+error.message);}finally{event.target.value='';}};
$('#clear-data').onclick=async()=>{if(busy)return;if(prompt('Esta ação apaga atletas, sorteio e partidas apenas da pelada selecionada. As outras peladas e sua conta serão preservadas. Exporte um backup antes. Digite APAGAR para confirmar:')!=='APAGAR')return;if(await commit({...emptyState(),groupName:state.groupName},'Dados desta pelada apagados. As outras peladas foram preservadas.')){ui.selected.clear();$('#settings-dialog').close();render();}};
document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){if(!busy)document.getElementById(close.dataset.close).close();return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='reload'){await load();return;}if(['create-league','open-league','delete-league','claim-guest','go-login','cancel-auth'].includes(action)){await accountAction(action,button.dataset.id);return;}if(!ready)return;try{
 if(action==='new-player')openPlayer();
 else if(action==='edit-player')openPlayer(button.dataset.id);
 else if(action==='archive-player'){const p=state.players.find(p=>p.id===button.dataset.id);if(!p||busy)return;if(p.active&&!confirm(`Arquivar ${p.name}? O histórico será preservado.`))return;await commit({...state,players:state.players.map(x=>x.id===p.id?{...x,active:!x.active}:x)},p.active?'Atleta arquivado.':'Atleta de volta ao elenco.');}
 else if(action==='demo'){if(state.players.length||state.matches.length)return notify('Os exemplos só podem ser carregados em uma pelada vazia.');if(await commit(demoState(today()),'Exemplo carregado. Todos os nomes e resultados são fictícios.')){ui.selected=new Set(activePlayers().map(p=>p.id));render();}}
 else if(action==='select-all'||action==='select-none'){ui.selected=new Set(action==='select-all'?activePlayers().map(p=>p.id):[]);$('#draw-list').innerHTML=drawList();updateDrawCount();}
 else if(action==='draw'){if(busy||conflicted)return;button.textContent='Equilibrando…';button.disabled=true;await new Promise(resolve=>setTimeout(resolve,0));try{const players=activePlayers().filter(p=>ui.selected.has(p.id));const draw=balancedDraw(players,ui.teamCount);await commit({...state,draw},'Times sorteados. Que vença a resenha.');}finally{if($('#draw-button')){$('#draw-button').innerHTML=icon('shuffle')+'Sortear times';updateDrawCount();}}}
 else if(action==='swap'){const draw=swapPlayers(state.draw,$('#swap-a').value,$('#swap-b').value);await commit({...state,draw},'Troca confirmada. Médias atualizadas.');}
 else if(action==='new-match'){openMatch(fromDraw(state,$('#match-team-a').value,$('#match-team-b').value,today()));}
 else if(action==='edit-match'){const match=state.matches.find(m=>m.id===button.dataset.id);if(match)openMatch(match);}
 else if(action==='delete-match'){if(!confirm('Excluir esta partida? Gols, notas e participações dela serão removidos dos rankings.'))return;await commit({...state,matches:state.matches.filter(m=>m.id!==button.dataset.id)},'Partida excluída. Rankings recalculados.');}
 else if(action==='share-teams')await shareTeams();
 else if(action==='export-ranking')exportRanking();
 else if(action==='clear-dates'){ui.matchFrom='';ui.matchTo='';render();}
 }catch(error){notify(error.message);}});
document.addEventListener('input',event=>{const target=event.target;
 if(target.id==='athlete-search'){ui.search=target.value;$('#athlete-list').innerHTML=athleteCards();setBusy(busy);}
 else if(target.id==='draw-search'){ui.drawSearch=target.value;$('#draw-list').innerHTML=drawList();}
});
document.addEventListener('change',event=>{const t=event.target;
 if(t.dataset.selectPlayer){if(t.checked)ui.selected.add(t.dataset.selectPlayer);else ui.selected.delete(t.dataset.selectPlayer);updateDrawCount();}
 else if(t.id==='team-count'){ui.teamCount=Number(t.value);updateDrawCount();}
 else if(t.id==='athlete-position'||t.id==='show-archived'){ui.position=$('#athlete-position').value;ui.archived=$('#show-archived').checked;$('#athlete-list').innerHTML=athleteCards();setBusy(busy);}
 else if(t.id==='match-from'||t.id==='match-to'){ui.matchFrom=$('#match-from').value;ui.matchTo=$('#match-to').value;$('#matches-list').innerHTML=matchesList();setBusy(busy);}

 else if(['rank-metric','rank-period','rank-min'].includes(t.id)){ui.metric=$('#rank-metric').value;ui.period=$('#rank-period').value;ui.minRated=Number($('#rank-min').value);render();}
});

async function accountTask(work,errorSelector){
 if(authBusy||busy)return;authBusy=true;setBusy(busy);
 try{return await work();}catch(error){if(errorSelector&&$(errorSelector))$(errorSelector).textContent=error.message;else notify(error.message);}finally{authBusy=false;setBusy(busy);}
}
async function accountAction(action,key){
 if(action==='go-login'||action==='cancel-auth'){ui.authView=action==='go-login';ui.authMode='login';render();return;}
 if(!session?.profile)return;
 if(action==='create-league'){if(authBusy||busy)return;newLeagueId=id();$('#league-name').value='';$('#league-error').textContent='';$('#league-dialog').showModal();setBusy(busy);return;}
 await accountTask(async()=>{
  if(action==='open-league'){authBusy=false;await openLeague(key);return;}
  if(action==='delete-league'){
   const league=leagues.find(l=>l.id===key);if(!league)return;
   if(prompt(`Excluir a pelada “${league.name}” e todos os seus registros? As outras peladas serão preservadas. Exporte um backup antes. Digite EXCLUIR para confirmar:`)!=='EXCLUIR')return;
   await api('/api/leagues/'+key,{method:'DELETE',body:JSON.stringify({revision:league.revision})});
   if(activeLeagueId===key){activeLeagueId=null;ready=false;state=emptyState();rememberLeague(null);loadGeneration++;}
   await refreshAccount();ui.view='peladas';render();notify('Pelada excluída. As outras foram preservadas.');
  }else if(action==='claim-guest'){
   if(!confirm('Transferir as peladas de convidado deste navegador para a sua conta atual?'))return;
   const result=await api('/api/auth/claim-guest',{method:'POST',body:'{}'});await refreshAccount();render();notify(result.claimed+' pelada(s) transferidas para sua conta.');
  }else if(action==='import-legacy'){
   return;
  }
 });
}
function openAccount(){
 if(!session?.profile){ui.authView=true;ui.authMode='login';ui.view='peladas';render();return;}
 const profile=session.profile;
 $('#account-fields').innerHTML=`<p class="help">${profile.kind==='guest'?'Convidado local: seus registros ficam neste navegador. Entre em uma conta para transferi-los para a nuvem.':'Seu acesso usa e-mail e senha. Nome, telefone e posição podem ser atualizados abaixo.'}</p><form id="profile-form"><label for="profile-name">Nome ou apelido</label><input id="profile-name" value="${h(profile.name)}" maxlength="50" minlength="2" required>${profile.email?`<label for="profile-email">E-mail de acesso</label><input id="profile-email" value="${h(profile.email)}" type="email" readonly>`:''}<label for="profile-phone">Telefone com DDD ${profile.kind==='guest'?'(opcional)':''}</label><input id="profile-phone" type="tel" value="${h(profile.phone||'')}" maxlength="24" ${profile.kind==='guest'?'':'required'}><label for="profile-position">Posição</label><select id="profile-position">${Object.entries(POSITIONS).map(([key,label])=>`<option value="${key}" ${profile.position===key?'selected':''}>${label}</option>`).join('')}</select><button class="button primary" data-account-write>Salvar perfil</button><p id="profile-error" class="form-error" role="alert"></p></form><hr>${profile.kind==='guest'?'<button class="button primary" id="show-login">Entrar / criar conta</button>':''}<button id="logout-account" class="button secondary">Sair</button>`;
 $('#account-dialog').showModal();setBusy(busy);
}
$('#account-button').onclick=openAccount;
$('#active-league-select').addEventListener('change',event=>{event.stopPropagation();openLeague(event.target.value);});
$('#league-form').addEventListener('submit',event=>{event.preventDefault();accountTask(async()=>{
 const result=await api('/api/leagues',{method:'POST',body:JSON.stringify({id:newLeagueId,name:$('#league-name').value.trim()})});
 await refreshAccount();$('#league-dialog').close();authBusy=false;ui.view='inicio';await openLeague(result.id);notify('Pelada criada. Hora de reunir a turma.');
},'#league-error');});
document.addEventListener('submit',event=>{
 if(event.target.id==='guest-form'){event.preventDefault();accountTask(async()=>{await api('/api/auth/guest',{method:'POST',body:JSON.stringify({name:$('#guest-name').value.trim()})});await refreshAccount();ui.authView=false;activeLeagueId=null;ready=false;ui.view='peladas';render();},'#guest-error');}
 if(event.target.id==='register-form'){event.preventDefault();accountTask(async()=>{await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:$('#register-name').value.trim(),email:$('#register-email').value.trim(),phone:$('#register-phone').value,position:$('#register-position').value,password:$('#register-password').value})});await refreshAccount();ui.authView=false;activeLeagueId=null;ready=false;ui.view='peladas';render();notify('Conta criada. Bem-vindo ao Várzuno.');},'#register-error');}
 if(event.target.id==='login-form'){event.preventDefault();accountTask(async()=>{await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#login-email').value.trim(),password:$('#login-password').value})});await refreshAccount();ui.authView=false;activeLeagueId=null;ready=false;ui.view='peladas';render();notify('Você entrou na sua conta.');},'#login-error');}
 if(event.target.id==='profile-form'){event.preventDefault();accountTask(async()=>{const result=await api('/api/profile',{method:'PUT',body:JSON.stringify({name:$('#profile-name').value.trim(),phone:$('#profile-phone').value,position:$('#profile-position').value})});session.profile=result.profile;render();notify('Perfil atualizado.');},'#profile-error');}
});
document.addEventListener('click',event=>{
 const tab=event.target.closest('[data-auth-mode]');if(tab){ui.authMode=tab.dataset.authMode;ui.authView=true;render();}
 if(event.target.closest('#show-login')){$('#account-dialog').close();ui.authView=true;ui.authMode='login';render();}
 if(event.target.closest('#logout-account'))accountTask(async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});$('#account-dialog').close();activeLeagueId=null;ready=false;state=emptyState();await refreshAccount();ui.authMode='login';ui.authView=false;ui.view='peladas';render();});
});
$('#view').innerHTML='<div class="loading">Abrindo o vestiário…</div>';
route();load();
